#!/usr/bin/env __RUNTIME__
// rustify launcher v3 (generated by templates/npm/pack.mjs — do not edit).
// (v3: under bun, the binary starts with the environment the command was
// started with, not with bun's process.env, which also holds the working
// directory's .env files.)
//
// Runs the native binary that the package manager installed for this machine
// as an optional dependency. No install script is involved.
//
// It is meant to run once. The first run rewires the command so that later
// runs start the binary without any JavaScript runtime:
//
//   Linux, macOS   replaces this file with a hard link to the binary
//   Windows        keeps a native copy beside this file and points the
//                  package manager's command shim (bun's .bunx, npm's .cmd)
//                  straight at it
//
// Every step is checked first and skipped when anything looks unfamiliar; the
// command then keeps working through this launcher, only slower.
//
// Set RUSTIFY_NO_LINK=1 to leave all files untouched.
"use strict";

const fs = require("fs");
const path = require("path");

// ──────────────────────── the binary's environment ─────────────────────────

// Before this file runs, bun has loaded the .env files of the working
// directory (.env, .env.local, .env.<NODE_ENV>, …, and an --env-file in
// BUN_OPTIONS) into process.env. It has not put them into the environment the
// operating system keeps for this process, so that one is read instead. The
// binary, and any JavaScript it hands a command back to, then start with what
// the user's shell gave the command, as they do once this launcher is out of
// the way: no .env value looks like a variable of the user's, and a NODE_ENV
// from .env does not make the next bun read .env.<NODE_ENV>.
//
// node loads no .env file for this file (it refuses --env-file in
// NODE_OPTIONS), so under node process.env is already that environment.
// Whenever it cannot be read, or what was read does not look like it (see
// plausible), process.env is used, as by launcher v2.
//
// What cannot be passed on as it is: a name that is not UTF-8 (on Windows,
// one with a lone surrogate) is left out, as v2 left it out on Linux; a value
// that is not UTF-8 arrives with U+FFFD in place of the bad bytes, as in v2;
// of two entries with the same name (on Windows in other letters, as Windows
// compares them: see windowsKey) the first is kept, which is the one
// getenv() and GetEnvironmentVariableW() find; an entry without "=" is left
// out. Names that are array indices ("1", "42") come first, in numeric
// order, as they always did in process.env.

// The entries ("NAME=value") of the environment this process was started
// with, as the operating system holds it: Buffers on Linux and macOS, text on
// Windows. null under node, or when it cannot be read.
function startEntries() {
  if (!process.versions.bun) return null;
  try {
    if (process.platform === "linux" || process.platform === "android") return procEntries();
    if (process.platform === "darwin") return darwinEntries();
    if (process.platform === "win32") return windowsEntries();
  } catch {}
  return null;
}

// Linux: the environment the kernel handed to this process, NUL-separated.
function procEntries() {
  const raw = fs.readFileSync("/proc/self/environ");
  const entries = [];
  for (let start = 0; start < raw.length; ) {
    let end = raw.indexOf(0, start);
    if (end < 0) end = raw.length;
    entries.push(raw.subarray(start, end));
    start = end + 1;
  }
  return entries;
}

// macOS: the C runtime's `environ`, through bun:ffi.
function darwinEntries() {
  const { dlopen, read, toBuffer, FFIType } = require("bun:ffi");
  const lib = dlopen("/usr/lib/libSystem.B.dylib", {
    _NSGetEnviron: { args: [], returns: FFIType.ptr },
    strlen: { args: [FFIType.ptr], returns: FFIType.u64_fast },
  });
  try {
    const environ = read.ptr(lib.symbols._NSGetEnviron(), 0);
    if (!environ) return null;
    const entries = [];
    for (let at = 0; ; at += 8) {
      const entry = read.ptr(environ, at);
      if (!entry) break;
      entries.push(Buffer.from(toBuffer(entry, 0, Number(lib.symbols.strlen(entry)))));
    }
    return entries;
  } finally {
    lib.close();
  }
}

// Windows: the process's environment block, through bun:ffi. It also holds
// the hidden "=C:=C:\…" entries (the working directory of each drive), which
// process.env leaves out and which bun passes on when they are given.
function windowsEntries() {
  const { dlopen, toBuffer, FFIType } = require("bun:ffi");
  const lib = dlopen("kernel32.dll", {
    GetEnvironmentStringsW: { args: [], returns: FFIType.ptr },
    FreeEnvironmentStringsW: { args: [FFIType.ptr], returns: FFIType.i32 },
    lstrlenW: { args: [FFIType.ptr], returns: FFIType.i32 },
  });
  try {
    const block = lib.symbols.GetEnvironmentStringsW();
    if (!block) return null;
    try {
      let units = 0;
      for (let length; (length = lib.symbols.lstrlenW(block + units * 2)) > 0; ) units += length + 1;
      const text = Buffer.from(toBuffer(block, 0, units * 2)).toString("utf16le");
      return text.split("\0").filter(Boolean);
    } finally {
      lib.symbols.FreeEnvironmentStringsW(block);
    }
  } finally {
    lib.close();
  }
}

let strictUtf8;
// `bytes` as UTF-8 text, or null when they are not UTF-8.
function utf8(bytes) {
  strictUtf8 = strictUtf8 || new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
  try {
    return strictUtf8.decode(bytes);
  } catch {
    return null;
  }
}

// A Windows variable's name as Windows compares it: one UTF-16 unit at a
// time, each in capitals where it has a capital of one unit whose small
// letter it is. So "été" and "ÉTÉ" are one name (and "ǆ" and "Ǆ"), while
// "straße" and "STRASSE" are two, as are "ı" and "I", "ſ" and "S", "ς" and
// "Σ", "ǅ" and "Ǆ", which toUpperCase() makes one (Windows 11, measured).
// Without the u flag a pair of surrogates is two units, and stays as it is,
// as on Windows. Not matched: letters that got capitals after Windows' table
// was made (Georgian "ა" and "Ა", Unicode 11), which Windows keeps apart.
function windowsKey(name) {
  return name.replace(/[a-z\u0080-￿]/g, (unit) => {
    const upper = unit.toUpperCase();
    return upper.length === 1 && upper.toLowerCase() === unit ? upper : unit;
  });
}

// The environment that `entries` (see startEntries) make, as an object for
// process.execve and spawn. See the top of this part for what is left out.
function environmentOf(entries, windows) {
  const env = {};
  const seen = new Set();
  for (const entry of entries) {
    let name;
    let value;
    if (typeof entry === "string") {
      // On Windows a name may start with "=": "=C:=C:\Users".
      const eq = entry.indexOf("=", windows ? 1 : 0);
      if (eq < 0) continue;
      name = entry.slice(0, eq);
      if (typeof name.isWellFormed === "function" && !name.isWellFormed()) continue;
      value = entry.slice(eq + 1);
    } else {
      const eq = entry.indexOf(0x3d, windows ? 1 : 0);
      if (eq < 0) continue;
      name = utf8(entry.subarray(0, eq));
      if (name === null) continue;
      value = entry.toString("utf8", eq + 1);
    }
    const key = windows ? windowsKey(name) : name;
    if (seen.has(key)) continue;
    seen.add(key);
    env[name] = value;
  }
  return env;
}

// What bun takes out of process.env when it uses it: the IPC channel that
// child_process.fork gave it. Left out here too, as v2 left it out.
const TAKEN = ["NODE_CHANNEL_FD", "NODE_CHANNEL_SERIALIZATION_MODE", "NODE_UNIQUE_ID"];

// Whether `env` can be what this process was started with: bun's process.env
// holds every variable of it, and more (the .env files) but never fewer. Any
// name it lacks means that something else was read, and so does nothing read
// where process.env has something. On Windows, names are matched in
// toUpperCase()'s capitals, which join more names than Windows does, so a
// name is not taken for unknown because process.env holds it in other
// letters; and a name with a unit outside ASCII does not count, because bun
// leaves some of them out of process.env there ("aß", "éa", "aÿ"; bun 1.4.2),
// though the block has them and a child gets them.
function plausible(env, windows) {
  const names = Object.keys(env);
  if (!names.length) return !Object.keys(process.env).length;
  const known = new Set(Object.keys(process.env).map((name) => (windows ? name.toUpperCase() : name)));
  if (!windows) return names.every((name) => !name || known.has(name));
  return names.every((name) => name.startsWith("=") || /[^\0-\x7f]/.test(name) || known.has(name.toUpperCase()));
}

// The environment the binary starts with: the one this process was started
// with (see startEntries), else process.env; and `rootName` naming the
// package's directory.
function binaryEnvironment(entries, rootName, root, windows) {
  let env = null;
  try {
    if (entries) env = environmentOf(entries, windows);
    if (env) for (const name of TAKEN) if (!(name in process.env)) delete env[name];
    if (env && !plausible(env, windows)) env = null;
  } catch {
    env = null;
  }
  if (!env) env = Object.assign({}, process.env);
  // On Windows a variable is one in any letter case (see windowsKey).
  if (windows) for (const name of Object.keys(env)) if (name !== rootName && windowsKey(name) === windowsKey(rootName)) delete env[name];
  env[rootName] = root;
  return env;
}

// ─────────────────────── Windows command shims ───────────────────────────

// bun's `<command>.bunx` (UTF-16LE), as written by bun's BinLinkingShim:
//
//   with a shebang:  bin_path  '"' NUL  launcher ' '  u32 bin_path_bytes
//                    u32 launcher_bytes  u16 flags
//   direct:          bin_path  '"' NUL  u16 flags
//
// flags: bit0 is_node_or_bun, bit1 is_node, bit2 has_shebang,
//        bit3 is_absolute_target, bits 4.. format version.
const BUNX_VERSION = 2739; // "V5". Anything else is left alone.

// Returns the direct form of a shebang `.bunx` whose target gains `suffix`,
// or null when the file is not exactly the known format.
function directBunx(buf, suffix) {
  if (!Buffer.isBuffer(buf) || buf.length < 16 || buf.length % 2) return null;
  const flags = buf.readUInt16LE(buf.length - 2);
  if (flags >> 4 !== BUNX_VERSION || !(flags & 0b100)) return null;
  const pathBytes = buf.readUInt32LE(buf.length - 10);
  const launcherBytes = buf.readUInt32LE(buf.length - 6);
  if (pathBytes % 2 || launcherBytes % 2 || pathBytes === 0) return null;
  if (buf.length !== pathBytes + 4 + launcherBytes + 8 + 2) return null;
  if (buf.readUInt16LE(pathBytes) !== 0x22 || buf.readUInt16LE(pathBytes + 2) !== 0) return null;
  const tail = Buffer.alloc(6);
  tail.writeUInt16LE(0x22, 0);
  tail.writeUInt16LE(0, 2);
  tail.writeUInt16LE(flags & ~0b111, 4);
  return Buffer.concat([buf.subarray(0, pathBytes), Buffer.from(suffix, "utf16le"), tail]);
}

// The target a `.bunx` names, as text, or null.
function bunxTarget(buf) {
  if (!Buffer.isBuffer(buf) || buf.length < 8 || buf.length % 2) return null;
  const flags = buf.readUInt16LE(buf.length - 2);
  if (flags >> 4 !== BUNX_VERSION) return null;
  const pathBytes = flags & 0b100 ? buf.readUInt32LE(buf.length - 10) : buf.length - 6;
  if (pathBytes <= 0 || pathBytes > buf.length) return null;
  return { path: buf.subarray(0, pathBytes).toString("utf16le"), absolute: Boolean(flags & 0b1000) };
}

function samePath(a, b) {
  return path.resolve(a).toLowerCase() === path.resolve(b).toLowerCase();
}

function replaceFile(file, content) {
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, content);
  try {
    fs.renameSync(tmp, file);
  } catch (err) {
    try {
      fs.unlinkSync(tmp);
    } catch {}
    throw err;
  }
}

// bun: point `<shimDir>\<name>.bunx` at the native copy instead of this launcher.
function retargetBun(shimDir, name, launcher) {
  const file = path.join(shimDir, `${name}.bunx`);
  let buf;
  try {
    buf = fs.readFileSync(file);
  } catch {
    return false;
  }
  const target = bunxTarget(buf);
  if (!target) return false;
  // Relative targets start at the parent of the shim's directory.
  const resolved = target.absolute ? target.path : path.resolve(path.dirname(shimDir), target.path);
  if (!samePath(resolved, launcher)) return false;
  const direct = directBunx(buf, ".exe");
  if (!direct) return false;
  replaceFile(file, direct);
  return true;
}

// npm: rewrite `<shimDir>\<name>.cmd`, `.ps1` and the sh shim to start the
// native copy. Each is rewritten only if it currently starts this launcher.
function retargetNpm(shimDir, name, launcher, native) {
  const cmd = path.join(shimDir, `${name}.cmd`);
  const relLauncher = path.relative(shimDir, launcher);
  let current;
  try {
    current = fs.readFileSync(cmd, "utf8");
  } catch {
    return false;
  }
  if (!current.toLowerCase().includes(`${path.sep}${relLauncher.toLowerCase()}"`)) return false;
  const win = path.relative(shimDir, native);
  const posix = win.split(path.sep).join("/");
  replaceFile(cmd, `@ECHO off\r\n"%~dp0${win}" %*\r\n`);
  const shims = {
    [`${name}.ps1`]:
      `#!/usr/bin/env pwsh\n$exe = Join-Path $PSScriptRoot "${posix}"\n` +
      `if ($MyInvocation.ExpectingInput) { $input | & $exe @args } else { & $exe @args }\n` +
      `exit $LASTEXITCODE\n`,
    [name]:
      `#!/bin/sh\nbasedir=$(dirname "$(echo "$0" | sed -e 's,\\\\,/,g')")\n` +
      `exec "$basedir/${posix}" "$@"\n`,
  };
  for (const [file, content] of Object.entries(shims)) {
    const target = path.join(shimDir, file);
    try {
      if (fs.readFileSync(target, "utf8").includes(relLauncher.split(path.sep).join("/"))) {
        replaceFile(target, content);
      }
    } catch {}
  }
  return true;
}

// Finds the shims that start `launcher` and points them at `native`.
function retargetShims(root, name, launcher, native) {
  let modules = path.dirname(root);
  if (path.basename(modules).startsWith("@")) modules = path.dirname(modules);
  if (path.basename(modules) !== "node_modules") return;
  const candidates = [
    process.env.BUN_INSTALL_BIN,
    path.resolve(modules, "..", "..", "..", "bin"), // bun global: <BUN_INSTALL>\bin
    path.dirname(modules), // npm global: <prefix>
    path.join(modules, ".bin"), // local installs
  ];
  for (const dir of candidates) {
    if (!dir) continue;
    try {
      if (retargetBun(dir, name, launcher) || retargetNpm(dir, name, launcher, native)) return;
    } catch {}
  }
}

// ─────────────────────────────── launcher ────────────────────────────────

function main() {
  const self = fs.realpathSync(__filename);
  const binDir = path.dirname(self);
  const root = path.dirname(binDir);
  const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
  const cfg = pkg.rustify || {};
  const bins = cfg.bins || {};
  const isWindows = process.platform === "win32";
  const exe = isWindows ? ".exe" : "";
  const name = path.basename(self);

  function die(message) {
    console.error(`${pkg.name}: ${message}`);
    process.exit(1);
  }

  const os = process.platform === "android" ? "linux" : process.platform;
  const key = `${os}-${process.arch}`;
  const dep = `${pkg.name}-${key}`;

  function platformDir() {
    if (!(pkg.optionalDependencies || {})[dep]) {
      const have = Object.keys(pkg.optionalDependencies || {})
        .filter((d) => d.startsWith(`${pkg.name}-`))
        .map((d) => d.slice(pkg.name.length + 1));
      die(`no prebuilt binary for ${key}. Available: ${have.join(", ") || "none"}.`);
    }
    try {
      return path.dirname(require.resolve(`${dep}/package.json`, { paths: [root] }));
    } catch {
      die(
        `the binary package for ${key} is not installed.\n` +
          `It is an optional dependency, so this happens when optional dependencies ` +
          `are skipped (--omit=optional, --no-optional) or the download failed.\n` +
          `Reinstall ${pkg.name} with optional dependencies enabled.`,
      );
    }
  }

  const nativePath = (dir, npmBin) => path.join(dir, "bin", bins[npmBin] + exe);

  // Put `src` at `dest` in one step, as a hard link where the filesystem
  // allows and as a copy otherwise.
  function place(src, dest) {
    const tmp = `${dest}.${process.pid}.tmp`;
    try {
      fs.linkSync(src, tmp);
    } catch {
      fs.copyFileSync(src, tmp);
      fs.chmodSync(tmp, 0o755);
    }
    try {
      fs.renameSync(tmp, dest);
    } catch (err) {
      try {
        fs.unlinkSync(tmp);
      } catch {}
      throw err;
    }
  }

  // True when `copy` is an up-to-date hard link or copy of `src`.
  function current(src, copy) {
    try {
      const x = fs.statSync(src);
      const y = fs.statSync(copy);
      return x.size === y.size && y.mtimeMs >= x.mtimeMs;
    } catch {
      return false;
    }
  }

  // Returns the path to run: a native file inside this package's bin
  // directory when linking works, otherwise the binary in the platform package.
  function prepare(dir) {
    const fallback = nativePath(dir, name);
    if (!fs.existsSync(fallback)) {
      die(`${fallback} is missing. Reinstall ${pkg.name}.`);
    }
    const linkable =
      !process.env.RUSTIFY_NO_LINK && !process.versions.pnp && !self.includes(".zip");
    if (!linkable) return fallback;
    try {
      if (isWindows) {
        // The shim the package manager wrote is bound to this script, so the
        // script stays. Keep a native copy beside it and repoint the shim.
        const side = path.join(binDir, name + exe);
        if (!current(fallback, side)) place(fallback, side);
        try {
          retargetShims(root, name, self, side);
        } catch {}
        return side;
      }
      // Replace every launcher of this package, not only the one that ran.
      for (const npmBin of Object.keys(bins)) {
        const target = path.join(binDir, npmBin);
        if (npmBin === name || fs.existsSync(target)) {
          place(nativePath(dir, npmBin), target);
        }
      }
      return self;
    } catch {
      return fallback;
    }
  }

  if (!bins[name]) die(`${name} is not a command of this package.`);
  const binary = prepare(platformDir());
  const args = process.argv.slice(2);
  // The root variable tells the binary where the npm package is when it runs
  // from the platform package instead of from this package's bin directory.
  const env = binaryEnvironment(startEntries(), cfg.rootEnv || "RUSTIFY_PACKAGE_ROOT", root, isWindows);

  if (!isWindows && typeof process.execve === "function") {
    try {
      process.execve(binary, [name, ...args], env);
    } catch {}
  }

  const child = require("child_process").spawn(binary, args, {
    stdio: "inherit",
    env,
    argv0: name,
  });
  child.on("error", (err) => die(`cannot start ${binary}: ${err.message}`));
  // The terminal already delivers Ctrl+C to the child. Staying alive here
  // keeps the shell waiting until the child has finished.
  process.on("SIGINT", () => {});
  for (const signal of ["SIGTERM", "SIGHUP", "SIGQUIT"]) {
    try {
      process.on(signal, () => child.kill(signal));
    } catch {}
  }
  child.on("exit", (code, signal) => {
    if (signal) {
      process.removeAllListeners(signal);
      process.kill(process.pid, signal);
      return;
    }
    process.exit(code === null ? 1 : code);
  });
}

if (require.main === module) main();
else module.exports = { BUNX_VERSION, directBunx, bunxTarget, retargetBun, retargetNpm, startEntries, environmentOf, binaryEnvironment, windowsKey };
